import { produce } from 'immer'
import type { ElementKind, Point, Snapshot } from './types'

type ElementFields = {
  readonly name?: string
  readonly description?: string
  readonly technology?: string
  readonly tags?: ReadonlyArray<string>
  readonly external?: boolean
}

type RelationshipFields = {
  readonly description?: string
  readonly technology?: string
}

/**
 * Edit commands. Ids are generated by the caller (`crypto.randomUUID()`) and passed in, so the reducer stays pure.
 * The reducer applies edits only; every model rule (parent kinds, endpoints, …) is validated by Core.
 */
export type EditorAction =
  | {
      readonly type: 'addElement'
      readonly id: string
      readonly kind: ElementKind
      readonly name: string
      readonly parentId: string | null
      readonly technology?: string
      readonly placement?: { readonly viewKey: string; readonly position: Point }
    }
  | { readonly type: 'updateElement'; readonly id: string; readonly fields: ElementFields }
  | { readonly type: 'deleteElement'; readonly id: string }
  | {
      readonly type: 'addRelationship'
      readonly id: string
      readonly sourceId: string
      readonly targetId: string
      readonly description: string
      readonly technology?: string
    }
  | { readonly type: 'updateRelationship'; readonly id: string; readonly fields: RelationshipFields }
  | { readonly type: 'deleteRelationships'; readonly ids: ReadonlyArray<string> }
  | { readonly type: 'moveElements'; readonly viewKey: string; readonly positions: Readonly<Record<string, Point>> }
  | { readonly type: 'replaceLayout'; readonly viewKey: string; readonly positions: Readonly<Record<string, Point>> }

/** Whether an action changes the model itself rather than only its layout (layout changes need no new views from Core). */
export function changesModel(action: EditorAction): boolean {
  return action.type !== 'moveElements' && action.type !== 'replaceLayout'
}

/**
 * Apply one edit command. Pure (Immer): returns a new snapshot, or the same one when the command does nothing
 * (unknown id, empty name, self relationship, or a relationship identical to an existing one: same source,
 * target and description).
 */
export function apply(snapshot: Snapshot, action: EditorAction): Snapshot {
  return produce(snapshot, (draft) => {
    switch (action.type) {
      case 'addElement': {
        const name = action.name.trim()
        if (!name || draft.elements.some((e) => e.id === action.id)) return
        draft.elements.push({
          id: action.id,
          kind: action.kind,
          name,
          description: '',
          technology: action.technology?.trim() ?? '',
          tags: [],
          parentId: action.parentId,
          external: false,
        })
        if (action.placement)
          (draft.layout[action.placement.viewKey] ??= {})[action.id] = { ...action.placement.position }
        return
      }
      case 'updateElement': {
        const element = draft.elements.find((e) => e.id === action.id)
        const { name, description, technology, tags, external } = action.fields
        if (!element || name?.trim() === '') return
        if (name !== undefined) element.name = name.trim()
        if (description !== undefined) element.description = description.trim()
        if (technology !== undefined) element.technology = technology.trim()
        if (tags !== undefined) element.tags = [...new Set(tags.map((t) => t.trim()).filter(Boolean))]
        if (external !== undefined) element.external = external
        return
      }
      case 'deleteElement': {
        const removed = descendantsAndSelf(draft, action.id)
        if (removed.size === 0) return
        draft.elements = draft.elements.filter((e) => !removed.has(e.id))
        draft.relationships = draft.relationships.filter((r) => !removed.has(r.sourceId) && !removed.has(r.targetId))
        for (const positions of Object.values(draft.layout)) for (const id of removed) delete positions[id]
        return
      }
      case 'addRelationship': {
        const description = action.description.trim()
        const known = (id: string) => draft.elements.some((e) => e.id === id)
        const duplicate = draft.relationships.some(
          (r) =>
            r.id === action.id ||
            (r.sourceId === action.sourceId && r.targetId === action.targetId && (r.description ?? '') === description),
        )
        if (action.sourceId === action.targetId || !known(action.sourceId) || !known(action.targetId) || duplicate)
          return
        draft.relationships.push({
          id: action.id,
          sourceId: action.sourceId,
          targetId: action.targetId,
          description,
          technology: action.technology?.trim() ?? '',
        })
        return
      }
      case 'updateRelationship': {
        const relationship = draft.relationships.find((r) => r.id === action.id)
        if (!relationship) return
        if (action.fields.description !== undefined) relationship.description = action.fields.description.trim()
        if (action.fields.technology !== undefined) relationship.technology = action.fields.technology.trim()
        return
      }
      case 'deleteRelationships': {
        const ids = new Set(action.ids)
        draft.relationships = draft.relationships.filter((r) => !ids.has(r.id))
        return
      }
      case 'moveElements':
        Object.assign((draft.layout[action.viewKey] ??= {}), structuredClone(action.positions))
        return
      case 'replaceLayout':
        draft.layout[action.viewKey] = structuredClone(action.positions)
        return
    }
  })
}

function descendantsAndSelf(snapshot: Snapshot, id: string): Set<string> {
  if (!snapshot.elements.some((e) => e.id === id)) return new Set()
  const out = new Set([id])
  let grew = true
  while (grew) {
    grew = false
    for (const e of snapshot.elements)
      if (e.parentId != null && out.has(e.parentId) && !out.has(e.id)) {
        out.add(e.id)
        grew = true
      }
  }
  return out
}

/** Whether two snapshots differ in anything the user would save (model or layout). */
export function differs(a: Snapshot, b: Snapshot): boolean {
  return a !== b && JSON.stringify(a) !== JSON.stringify(b)
}
